import os
import pandas as pd
import numpy as np
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime
import logging

from config import get_artifacts_path
from utils.stats import benjamini_hochberg
from utils.logging import get_logger

logger = get_logger(__name__)

def load_selection_frequency() -> pd.DataFrame:
    """Load the selection frequency data generated by feature_selection.py."""
    reports_path = get_artifacts_path() / "reports"
    file_path = reports_path / "selection_frequency.csv"
    
    if not file_path.exists():
        raise FileNotFoundError(f"Selection frequency file not found: {file_path}")
    
    df = pd.read_csv(file_path)
    # Ensure frequency is numeric
    if 'frequency' in df.columns:
        df['frequency'] = pd.to_numeric(df['frequency'], errors='coerce').fillna(0)
    return df

def load_effect_sizes() -> pd.DataFrame:
    """Load the effect sizes calculated by feature_selection.py."""
    reports_path = get_artifacts_path() / "reports"
    file_path = reports_path / "effect_sizes.csv"
    
    if not file_path.exists():
        # Fallback: if effect_sizes.csv doesn't exist, try to load from the main metrics or selection file if it contains coefficients
        # However, per spec, T026 should have generated this. We raise if missing to ensure data integrity.
        raise FileNotFoundError(f"Effect sizes file not found: {file_path}")
    
    df = pd.read_csv(file_path)
    return df

def calculate_aggregated_metrics(selection_freq_df: pd.DataFrame, effect_sizes_df: pd.DataFrame) -> pd.DataFrame:
    """
    Merge selection frequency and effect sizes, calculate average effect size,
    and prepare the data for ranking.
    """
    # Merge on feature_id
    merged = pd.merge(
        selection_freq_df, 
        effect_sizes_df, 
        on='feature_id', 
        how='inner',
        suffixes=('_freq', '_eff')
    )
    
    # If multiple rows exist for same feature (different thresholds), aggregate
    # We take the max frequency and mean effect size across thresholds for the final report
    if 'threshold' in merged.columns:
        agg_df = merged.groupby('feature_id').agg({
            'frequency': 'max',  # Use the highest frequency observed across thresholds
            'effect_size': 'mean', # Average effect size
            'p_value': 'min' # Use the most significant p-value (min)
        }).reset_index()
    else:
        agg_df = merged.rename(columns={'effect_size': 'effect_size'})
        # Ensure p_value exists
        if 'p_value' not in agg_df.columns:
            agg_df['p_value'] = 0.0 
        
    return agg_df

def apply_significance_filter(df: pd.DataFrame, p_threshold: float = 0.05, freq_threshold: float = 0.5) -> pd.DataFrame:
    """
    Filter features based on BH-adjusted p-value and selection frequency.
    
    Args:
        df: DataFrame with 'p_value' and 'frequency' columns
        p_threshold: Maximum adjusted p-value (default 0.05)
        freq_threshold: Minimum selection frequency (default 0.5)
        
    Returns:
        Filtered DataFrame
    """
    # Apply Benjamini-Hochberg if raw p-values are present and not yet adjusted
    # Assuming 'p_value' column contains raw p-values from the model
    if 'p_value' in df.columns:
        # Filter out non-numeric or infinite values first
        valid_p = df['p_value'].replace([np.inf, -np.inf], np.nan).dropna()
        if len(valid_p) > 0:
            # We need to apply BH to the column. 
            # Note: benjamini_hochberg returns adjusted values.
            # We assume the input p-values are raw.
            adjusted_p = benjamini_hochberg(df['p_value'].values)
            df['p_adjusted'] = adjusted_p
        else:
            df['p_adjusted'] = 1.0
    else:
        # If p_value is already adjusted or missing, use it or default
        if 'p_adjusted' not in df.columns:
            df['p_adjusted'] = df.get('p_value', 1.0)
    
    # Filter
    mask = (df['p_adjusted'] <= p_threshold) & (df['frequency'] >= freq_threshold)
    return df[mask].copy()

def rank_and_sort(df: pd.DataFrame) -> pd.DataFrame:
    """
    Rank features by selection frequency (desc) and effect size (abs desc).
    """
    if df.empty:
        return df
    
    # Sort by frequency descending, then by absolute effect size descending
    df = df.sort_values(
        by=['frequency', 'effect_size'], 
        ascending=[False, False]
    )
    
    # Add rank column
    df['rank'] = range(1, len(df) + 1)
    
    return df.reset_index(drop=True)

def generate_biomarker_report(
    p_threshold: float = 0.05,
    freq_threshold: float = 0.5,
    output_filename: str = "top_features.csv"
) -> str:
    """
    Main function to generate the top features biomarker report.
    
    1. Loads selection frequency and effect sizes.
    2. Aggregates metrics.
    3. Applies significance filtering (BH-adjusted p-value & frequency).
    4. Ranks and sorts features.
    5. Saves to artifacts/reports/top_features.csv.
    
    Returns:
        Path to the generated CSV file.
    """
    logger.info("Generating biomarker report...")
    
    # Load data
    try:
        freq_df = load_selection_frequency()
        eff_df = load_effect_sizes()
    except FileNotFoundError as e:
        logger.error(f"Missing required data files: {e}")
        raise
    
    # Calculate aggregated metrics
    agg_df = calculate_aggregated_metrics(freq_df, eff_df)
    
    if agg_df.empty:
        logger.warning("No features found after aggregation.")
        # Create an empty report with correct schema
        reports_path = get_artifacts_path() / "reports"
        reports_path.mkdir(parents=True, exist_ok=True)
        empty_df = pd.DataFrame(columns=['rank', 'feature_id', 'modality', 'frequency', 'p_adjusted', 'effect_size'])
        out_path = reports_path / output_filename
        empty_df.to_csv(out_path, index=False)
        return str(out_path)
    
    # Apply significance filter
    filtered_df = apply_significance_filter(agg_df, p_threshold=p_threshold, freq_threshold=freq_threshold)
    
    # Rank and sort
    ranked_df = rank_and_sort(filtered_df)
    
    # Ensure columns are in expected order for the report
    final_cols = ['rank', 'feature_id', 'modality', 'frequency', 'p_adjusted', 'effect_size']
    # Handle cases where 'modality' might be missing in the source data
    if 'modality' not in ranked_df.columns:
        # Infer from feature_id if possible (e.g., SNP_ vs MET_) or default
        # For now, we add a placeholder or try to parse
        def infer_modality(fid):
            if isinstance(fid, str):
                if fid.startswith('SNP') or fid.startswith('snp'): return 'SNP'
                if fid.startswith('MET') or fid.startswith('met'): return 'Metabolite'
            return 'Unknown'
        
        ranked_df['modality'] = ranked_df['feature_id'].apply(infer_modality)
    
    # Select and reorder columns
    report_df = ranked_df[final_cols]
    
    # Save to disk
    reports_path = get_artifacts_path() / "reports"
    reports_path.mkdir(parents=True, exist_ok=True)
    out_path = reports_path / output_filename
    
    report_df.to_csv(out_path, index=False)
    logger.info(f"Biomarker report saved to {out_path} with {len(report_df)} significant features.")
    
    return str(out_path)

def main():
    """CLI entry point for biomarker report generation."""
    import argparse
    
    parser = argparse.ArgumentParser(description="Generate top features biomarker report")
    parser.add_argument('--p-threshold', type=float, default=0.05, help="Significance threshold for adjusted p-value")
    parser.add_argument('--freq-threshold', type=float, default=0.5, help="Minimum selection frequency")
    parser.add_argument('--output', type=str, default="top_features.csv", help="Output filename")
    
    args = parser.parse_args()
    
    try:
        path = generate_biomarker_report(
            p_threshold=args.p_threshold,
            freq_threshold=args.freq_threshold,
            output_filename=args.output
        )
        print(f"Report generated: {path}")
    except Exception as e:
        logger.exception("Failed to generate biomarker report")
        raise

if __name__ == "__main__":
    main()
